// POPRAWNIE: sparametryzowany typ, waski zasieg, dozwolony modyfikator
class Repository {
    private List<String> cache = new ArrayList<>(); // sparametryzowany typ

    @SafeVarargs
    final void addAll(List<String>... lists) { // final - dozwolone dla @SafeVarargs
        for (List<String> list : lists) cache.addAll(list);
    }
}
